cypress_script:
describe('Numeric Input Field', () => {
  it('should retain valid numeric input', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('42').should('have.value', '42');
  });

  it('should not change value on invalid input', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('abc').should('have.value', '');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/inputs');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Numeric Input Field', () => {
  test('should retain valid numeric input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    const numericInput = page.locator('input[type="number"]');
    await numericInput.fill('42');
    await expect(numericInput).toHaveValue('42');
  });

  test('should not change value on invalid input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    const numericInput = page.locator('input[type="number"]');
    await numericInput.fill('abc');
    await expect(numericInput).toHaveValue('');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/inputs');
  });
});
